const collapseColossusSheet=new Image();collapseColossusSheet.assetSrc='assets/collapse-colossus-v2.png';
function beginCollapseColossus(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'collapseGravity',bespoke:true,windup:1.6,origin:{x:e.x,y:e.y},center:{x:e.x,y:e.y},first:false,second:false};}
// Shared radii for warning and impact. Gravity is terrain-constrained and cannot move an invulnerable player.
function collapseColossusContains(a,point,inner=false){let d=dist(a.origin,point);return inner?d<=220:d>=110&&d<=420;}
function pullCollapseColossus(a,before,after){let active=Math.max(0,Math.min(after,1.4)-Math.max(before,.4)),d=dist(a.origin,p);if(!active||p.inv>0||d<=35||d>420||!lineClear(a.origin,p))return;let step=Math.min(d-35,90*active);moveActor(p,(a.origin.x-p.x)/d*step,(a.origin.y-p.y)/d*step,18);}
const collapseColossusAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r11e4')return collapseColossusAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='collapseGravity'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=420&&clear){beginCollapseColossus(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,60*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,28)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;pullCollapseColossus(a,before,e.elapsed);
 if(!a.first&&e.elapsed>=1.6){a.first=true;e.struck=true;if(collapseColossusContains(a,p)&&lineClear(a.origin,p))hurt(80);playSound('impact',e.x,e.y);}
 if(!dead&&!a.second&&e.elapsed>=2.8){a.second=true;e.struck=true;if(collapseColossusContains(a,p,true)&&lineClear(a.origin,p))hurt(110);playSound('impact',e.x,e.y);}
 if(e.elapsed>=3.8){e.attack=null;e.state='idle';e.t=3;}
};
const collapseColossusDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r11e4'||!collapseColossusSheet.complete||!collapseColossusSheet.naturalWidth||!collapseColossusSheet.naturalHeight)return collapseColossusDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='collapseGravity')f={row:2,col:e.elapsed<1?0:e.elapsed<1.6?1:e.elapsed<1.9?2:e.elapsed<2.25?0:e.elapsed<2.8?1:e.elapsed<3.1?2:3};let q=project(e.x,e.y),sw=collapseColossusSheet.naturalWidth/4,sh=collapseColossusSheet.naturalHeight/3,w=370,h=w*sh/sw,anchor=[[.85,.85,.85,.85],[.82,.81,.78,.82],[.78,.79,.77,.77]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,collapseColossusSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(collapseColossusSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const collapseColossusSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r11e4'?270:collapseColossusSizeBase(e);
function drawCollapseColossusField(a,inner,impact){let q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=impact?'#e5b2ff88':'#ac72ed22';ctx.strokeStyle=impact?'#ffe3ff':'#d7a2ff';ctx.lineWidth=impact?4:2;ctx.beginPath();ctx.arc(0,0,inner?220:420,0,Math.PI*2);if(!inner){ctx.moveTo(110,0);ctx.arc(0,0,110,0,Math.PI*2,true);}ctx.fill();ctx.stroke();ctx.restore();}
const collapseColossusGroundBase=drawGroundEffects;drawGroundEffects=()=>{collapseColossusGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r11e4'):enemies)){let a=e.attack;if(e.species!=='r11e4'||e.hp<=0||a?.pattern!=='collapseGravity'||!visibleAt(a.origin.x,a.origin.y)||e.elapsed>=3.1)continue;let inner=e.elapsed>=1.85,impact=inner?e.elapsed>=2.8:e.elapsed>=1.6;drawCollapseColossusField(a,inner,impact);if(e.elapsed<1.4){for(let i=0;i<8;i++){let angle=i*Math.PI/4,r=420-(e.elapsed% .5)/.5*290,q=project(a.origin.x+Math.cos(angle)*r,a.origin.y+Math.sin(angle)*r),to=project(a.origin.x+Math.cos(angle)*(r-20),a.origin.y+Math.sin(angle)*(r-20));ctx.save();ctx.strokeStyle='#dca8ff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(to.x,to.y);ctx.stroke();ctx.restore();}}}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r11e4',animateEnemy,drawRegionEnemy);
